// Bab 3 Data Modeling: membangun tabel dimensi (surrogate key, unknown member, dimensi tanggal, SCD tipe 0/1/2/3).
// Setiap latihan dijalankan di transaksi yang dibatalkan, jadi skema dw dibuat ulang di setup setiap contoh dan soal.

// DW_DATE: hasil rujukan soal dimensi tanggal.
const DW_DATE = `create schema dw;
create table dw.dim_date (
  date_key integer primary key,
  full_date date not null unique,
  year integer not null,
  quarter integer not null,
  month integer not null,
  month_name text not null,
  day_of_month integer not null,
  day_of_week integer not null,
  day_name text not null,
  is_weekend boolean not null
);
insert into dw.dim_date
with tanggal as (
  select g::date as d
  from generate_series(date '2024-01-01', date '2025-12-31', interval '1 day') as g
)
select to_char(d, 'YYYYMMDD')::integer, d,
       extract(year from d), extract(quarter from d), extract(month from d),
       to_char(d, 'FMMonth'), extract(day from d),
       extract(isodow from d), to_char(d, 'FMDay'),
       extract(isodow from d) in (6, 7)
from tanggal;`;

// DW_PRODUCT: hasil rujukan soal dimensi produk (muatan pertama, termasuk unknown member).
const PRODUCT_TABLE = `create schema dw;
create table dw.dim_product (
  product_sk integer generated by default as identity primary key,
  product_id integer not null unique,
  sku text not null,
  product_name text not null,
  brand text not null,
  category_name text not null,
  parent_category_name text not null,
  is_active boolean not null
);`;
const PRODUCT_UNKNOWN = `insert into dw.dim_product (product_sk, product_id, sku, product_name, brand, category_name, parent_category_name, is_active)
values (-1, -1, 'Tidak diketahui', 'Produk tidak diketahui', 'Tidak diketahui', 'Tidak diketahui', 'Tidak diketahui', false);`;
const PRODUCT_UPSERT = `insert into dw.dim_product (product_id, sku, product_name, brand, category_name, parent_category_name, is_active)
select p.product_id, p.sku, p.product_name, p.brand, c.category_name, pc.category_name, p.is_active
from app.products as p
join app.categories as c on c.category_id = p.category_id
join app.categories as pc on pc.category_id = c.parent_id
order by p.product_id
on conflict (product_id) do update
set sku = excluded.sku,
    product_name = excluded.product_name,
    brand = excluded.brand,
    category_name = excluded.category_name,
    parent_category_name = excluded.parent_category_name,
    is_active = excluded.is_active;`;
const DW_PRODUCT = `${PRODUCT_TABLE}\n${PRODUCT_UNKNOWN}\n${PRODUCT_UPSERT}`;

// Perubahan di sumber untuk soal pemuatan ulang SCD tipe 1. sk_awal menyimpan surrogate key sebelum dimuat ulang.
const PRODUCT_CHANGES = `${DW_PRODUCT}
create table dw.sk_awal as select product_id, product_sk from dw.dim_product;
update app.products set product_name = 'Earphone Bluetooth Satria Hitam' where product_id = 1;
update app.products set category_id = 4 where product_id = 2;
update app.products set is_active = false where product_id = 3;
insert into app.products (product_id, sku, product_name, category_id, brand, list_price, is_active, created_at)
values (151, 'TK-11057', 'Speaker Mini Kirana', 4, 'Kirana', 189900, true, '2025-10-31');`;

// SCD2: isi dw.dim_customer dari raw.customer_snapshot.
const CUSTOMER_TABLE = `create schema dw;
create table dw.dim_customer (
  customer_sk integer generated always as identity primary key,
  customer_id integer not null,
  full_name text not null,
  city_id integer not null,
  city_name text not null,
  segment text not null,
  valid_from date not null,
  valid_to date not null,
  is_current boolean not null
);`;
const CUSTOMER_LOAD = `insert into dw.dim_customer (customer_id, full_name, city_id, city_name, segment, valid_from, valid_to, is_current)
with potret as (
  select snapshot_date, customer_id, full_name, city_id, segment,
         lag(city_id) over (partition by customer_id order by snapshot_date) as kota_sebelumnya,
         lag(segment) over (partition by customer_id order by snapshot_date) as segmen_sebelumnya
  from raw.customer_snapshot
),
awal_versi as (
  select snapshot_date, customer_id, full_name, city_id, segment
  from potret
  where kota_sebelumnya is null
     or city_id <> kota_sebelumnya
     or segment <> segmen_sebelumnya
),
versi as (
  select a.*,
         row_number() over (partition by customer_id order by snapshot_date) as nomor_versi,
         lead(snapshot_date) over (partition by customer_id order by snapshot_date) as awal_berikutnya
  from awal_versi as a
)
select v.customer_id, v.full_name, v.city_id, ci.city_name, v.segment,
       case when v.nomor_versi = 1 then cu.signup_date else v.snapshot_date end,
       coalesce(v.awal_berikutnya - 1, date '9999-12-31'),
       v.awal_berikutnya is null
from versi as v
join app.cities as ci on ci.city_id = v.city_id
join app.customers as cu on cu.customer_id = v.customer_id
order by v.customer_id, v.snapshot_date;`;
const DW_CUSTOMER = `${CUSTOMER_TABLE}\n${CUSTOMER_LOAD}`;

// Verify: hanya dibaca mesin, tidak ditampilkan ke pengguna.
const VERIFY_DATE = `select count(*) as baris,
       min(date_key) as key_awal,
       max(date_key) as key_akhir,
       count(distinct full_date) as tanggal_unik,
       count(*) filter (where date_key = to_char(full_date, 'YYYYMMDD')::integer) as key_cocok,
       count(*) filter (where year = extract(year from full_date) and quarter = extract(quarter from full_date)
                          and month = extract(month from full_date) and day_of_month = extract(day from full_date)) as bagian_cocok,
       count(*) filter (where month_name = to_char(full_date, 'FMMonth')) as nama_bulan_cocok,
       count(*) filter (where day_of_week = extract(isodow from full_date) and day_name = to_char(full_date, 'FMDay')) as hari_cocok,
       count(*) filter (where is_weekend) as akhir_pekan,
       count(*) filter (where is_weekend = (extract(isodow from full_date) in (6, 7))) as akhir_pekan_cocok
from dw.dim_date;`;

const VERIFY_PRODUCT = `select count(*) as baris,
       count(*) filter (where d.product_sk = -1 and d.product_id = -1 and d.product_name = 'Produk tidak diketahui'
                          and d.sku = 'Tidak diketahui' and d.brand = 'Tidak diketahui' and d.category_name = 'Tidak diketahui'
                          and d.parent_category_name = 'Tidak diketahui' and d.is_active = false) as unknown_member,
       count(distinct d.product_sk) as sk_unik,
       count(*) filter (where d.product_id > 0 and d.product_sk > 0) as sk_positif,
       count(*) filter (where d.sku = p.sku and d.product_name = p.product_name and d.brand = p.brand
                          and d.category_name = c.category_name and d.parent_category_name = pc.category_name
                          and d.is_active = p.is_active) as cocok_dengan_sumber
from dw.dim_product as d
left join app.products as p on p.product_id = d.product_id
left join app.categories as c on c.category_id = p.category_id
left join app.categories as pc on pc.category_id = c.parent_id;`;

const VERIFY_PRODUCT_RELOAD = `select count(*) as baris,
       count(*) filter (where d.product_sk = -1) as unknown_member,
       count(*) filter (where s.product_sk = d.product_sk) as sk_tetap,
       count(*) filter (where d.product_id = 151 and d.product_sk > 0) as produk_baru,
       count(*) filter (where d.sku = p.sku and d.product_name = p.product_name and d.brand = p.brand
                          and d.category_name = c.category_name and d.parent_category_name = pc.category_name
                          and d.is_active = p.is_active) as cocok_dengan_sumber
from dw.dim_product as d
left join dw.sk_awal as s on s.product_id = d.product_id
left join app.products as p on p.product_id = d.product_id
left join app.categories as c on c.category_id = p.category_id
left join app.categories as pc on pc.category_id = c.parent_id;`;

const VERIFY_CUSTOMER = `with potret as (
  select snapshot_date, customer_id, full_name, city_id, segment,
         lag(city_id) over (partition by customer_id order by snapshot_date) as kota_sebelumnya,
         lag(segment) over (partition by customer_id order by snapshot_date) as segmen_sebelumnya
  from raw.customer_snapshot
),
awal_versi as (
  select * from potret
  where kota_sebelumnya is null or city_id <> kota_sebelumnya or segment <> segmen_sebelumnya
),
versi as (
  select a.*,
         row_number() over (partition by customer_id order by snapshot_date) as nomor_versi,
         lead(snapshot_date) over (partition by customer_id order by snapshot_date) as awal_berikutnya
  from awal_versi as a
),
harapan as (
  select v.customer_id, v.full_name, v.city_id, ci.city_name, v.segment,
         case when v.nomor_versi = 1 then cu.signup_date else v.snapshot_date end as valid_from,
         coalesce(v.awal_berikutnya - 1, date '9999-12-31') as valid_to,
         v.awal_berikutnya is null as is_current
  from versi as v
  join app.cities as ci on ci.city_id = v.city_id
  join app.customers as cu on cu.customer_id = v.customer_id
)
select count(*) as baris,
       count(distinct d.customer_id) as pelanggan,
       count(distinct d.customer_sk) as sk_unik,
       count(*) filter (where d.is_current) as baris_current,
       (select count(*) from (select customer_id from dw.dim_customer group by customer_id
                              having count(*) filter (where is_current) = 1) as x) as pelanggan_satu_current,
       (select count(*) from dw.dim_customer as a join dw.dim_customer as b
          on a.customer_id = b.customer_id and a.customer_sk <> b.customer_sk
         and a.valid_from <= b.valid_to and b.valid_from <= a.valid_to) as tumpang_tindih,
       count(h.customer_id) as versi_cocok
from dw.dim_customer as d
left join harapan as h
  on h.customer_id = d.customer_id and h.full_name = d.full_name and h.city_id = d.city_id
 and h.city_name = d.city_name and h.segment = d.segment and h.valid_from = d.valid_from
 and h.valid_to = d.valid_to and h.is_current = d.is_current;`;

